-- 0. VARSA ESKİ GEÇİCİ TABLOYU TEMİZLE
IF OBJECT_ID('tempdb..#TempKitaplar') IS NOT NULL DROP TABLE #TempKitaplar;
GO

-- 1. KATEGORİLERİ GÜVENLE EKLE (Sadece Yoklarsa)
SET IDENTITY_INSERT [Kategoriler] ON;
IF NOT EXISTS (SELECT 1 FROM Kategoriler WHERE KategoriId = 1004) INSERT INTO Kategoriler (KategoriId, KategoriAdi, IkonSifi) VALUES (1004, 'Dünya Klasikleri', '🌍');
IF NOT EXISTS (SELECT 1 FROM Kategoriler WHERE KategoriId = 1005) INSERT INTO Kategoriler (KategoriId, KategoriAdi, IkonSifi) VALUES (1005, 'Türk Edebiyatı', '🇹🇷');
IF NOT EXISTS (SELECT 1 FROM Kategoriler WHERE KategoriId = 1006) INSERT INTO Kategoriler (KategoriId, KategoriAdi, IkonSifi) VALUES (1006, 'Bilim Kurgu & Fantastik', '🚀');
IF NOT EXISTS (SELECT 1 FROM Kategoriler WHERE KategoriId = 1007) INSERT INTO Kategoriler (KategoriId, KategoriAdi, IkonSifi) VALUES (1007, 'Polisiye & Gizem', '🕵️');
IF NOT EXISTS (SELECT 1 FROM Kategoriler WHERE KategoriId = 1008) INSERT INTO Kategoriler (KategoriId, KategoriAdi, IkonSifi) VALUES (1008, 'Felsefe & Düşünce', '🧠');
IF NOT EXISTS (SELECT 1 FROM Kategoriler WHERE KategoriId = 1009) INSERT INTO Kategoriler (KategoriId, KategoriAdi, IkonSifi) VALUES (1009, 'Kişisel Gelişim', '🌱');
SET IDENTITY_INSERT [Kategoriler] OFF;
GO

-- 2. GEÇİCİ TABLO OLUŞTUR VE VERİLERİ YÜKLE
CREATE TABLE #TempKitaplar (KitapId INT, KitapAdi NVARCHAR(255), YazarAdi NVARCHAR(255), Fiyat DECIMAL(18,2), Aciklama NVARCHAR(MAX), KategoriId INT, ResimUrl NVARCHAR(255));

GO

-- 3. SİSTEMDE OLMAYAN YAZARLARI OTOMATİK OLARAK EKLE
SELECT DISTINCT YazarAdi 
FROM #TempKitaplar 
WHERE YazarAdi NOT IN (SELECT AdSoyad FROM Yazarlar);
GO

-- 4. KİTAPLARI ASIL TABLOYA YAZAR VE KATEGORİ BAĞLANTISIYLA AKTAR
-- ** BU KISIM GÜNCELLENDİ (Zaten Varsa Eklemez) **
SET IDENTITY_INSERT Kitaplar ON;

SELECT 
    t.KitapId, 
    t.KitapAdi, 
    y.YazarId, 
    t.KategoriId, 
    t.Fiyat, 
    t.ResimUrl, 
    t.Aciklama, 
    50, -- Başlangıç olarak hepsine 50 stok veriyoruz
    1,  -- Yeni Çıkan vitrininde görünsün
    1   -- Çok Satan vitrininde görünsün
FROM #TempKitaplar t
INNER JOIN Yazarlar y ON t.YazarAdi = y.AdSoyad
WHERE NOT EXISTS (SELECT 1 FROM Kitaplar k WHERE k.KitapId = t.KitapId);

SET IDENTITY_INSERT Kitaplar OFF;
GO

-- 5. GEÇİCİ TABLOYU SİL
DROP TABLE #TempKitaplar;
GO